use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use sha2::{Sha256, Digest};
use aes_gcm::{Aes256Gcm, Key, Nonce};
use aes_gcm::aead::{Aead, NewAead};

const MAX_REQUESTS_PER_WINDOW: u32 = 100;
const WINDOW_DURATION_SECS: u64 = 60;
const INDEX_SHARD_COUNT: usize = 16;

#[derive(Clone)]
pub struct RateLimitEntry {
    count: u32,
    window_start: u64,
}

pub struct SearchIndexService {
    rate_limits: Arc<Mutex<HashMap<String, RateLimitEntry>>>,
    index_shards: Vec<Arc<Mutex<HashMap<String, Vec<u8>>>>>,
    encryption_key: [u8; 32],
}

impl SearchIndexService {
    pub fn new(key: [u8; 32]) -> Self {
        let mut shards = Vec::with_capacity(INDEX_SHARD_COUNT);
        for _ in 0..INDEX_SHARD_COUNT {
            shards.push(Arc::new(Mutex::new(HashMap::new())));
        }
        SearchIndexService {
            rate_limits: Arc::new(Mutex::new(HashMap::new())),
            index_shards: shards,
            encryption_key: key,
        }
    }

    fn get_current_window(&self) -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs()
            / WINDOW_DURATION_SECS
    }

    fn compute_client_identity(&self, api_key: &str, source_ip: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(api_key.as_bytes());
        hasher.update(b":");
        hasher.update(source_ip.as_bytes());
        let result = hasher.finalize();
        hex::encode(&result[..16])
    }

    fn check_rate_limit(&self, client_id: &str) -> Result<(), String> {
        let current_window = self.get_current_window();
        let mut limits = self.rate_limits.lock().unwrap();

        let entry = limits.entry(client_id.to_string()).or_insert(RateLimitEntry {
            count: 0,
            window_start: current_window,
        });

        if entry.window_start != current_window {
            entry.count = 0;
            entry.window_start = current_window;
        }

        entry.count += 1;

        if entry.count > MAX_REQUESTS_PER_WINDOW {
            return Err(format!("Rate limit exceeded for client {}", client_id));
        }

        Ok(())
    }

    fn check_rate_limit_n(&self, client_id: &str, n: u32) -> Result<(), String> {
        let current_window = self.get_current_window();
        let mut limits = self.rate_limits.lock().unwrap();

        let entry = limits.entry(client_id.to_string()).or_insert(RateLimitEntry {
            count: 0,
            window_start: current_window,
        });

        if entry.window_start != current_window {
            entry.count = 0;
            entry.window_start = current_window;
        }

        entry.count += n;

        if entry.count > MAX_REQUESTS_PER_WINDOW {
            return Err(format!("Rate limit exceeded for client {}", client_id));
        }

        Ok(())
    }

    fn select_shard(&self, document_id: &str) -> usize {
        let mut hasher = Sha256::new();
        hasher.update(document_id.as_bytes());
        let hash = hasher.finalize();
        let shard_idx = (hash[0] as usize) % INDEX_SHARD_COUNT;
        shard_idx
    }

    fn encrypt_document(&self, plaintext: &[u8], doc_id: &str) -> Result<Vec<u8>, String> {
        let key = Key::from_slice(&self.encryption_key);
        let cipher = Aes256Gcm::new(key);

        let mut nonce_bytes = [0u8; 12];
        let mut hasher = Sha256::new();
        hasher.update(doc_id.as_bytes());
        let nonce_seed = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        hasher.update(nonce_seed.to_le_bytes());
        let hash = hasher.finalize();
        nonce_bytes.copy_from_slice(&hash[..12]);
        let nonce = Nonce::from_slice(&nonce_bytes);

        let ciphertext = cipher.encrypt(nonce, plaintext)
            .map_err(|e| format!("Encryption failed: {}", e))?;

        // Prepend the nonce to the ciphertext so it can be recovered for
        // decryption. Without persisting the (non-deterministic) nonce the
        // ciphertext would be unrecoverable and forces unsafe nonce handling.
        let mut output = Vec::with_capacity(nonce_bytes.len() + ciphertext.len());
        output.extend_from_slice(&nonce_bytes);
        output.extend_from_slice(&ciphertext);
        Ok(output)
    }

    pub fn index_document(
        &self,
        api_key: &str,
        source_ip: &str,
        document_id: &str,
        content: &[u8],
    ) -> Result<String, String> {
        let client_id = self.compute_client_identity(api_key, source_ip);
        self.check_rate_limit(&client_id)?;

        let encrypted = self.encrypt_document(content, document_id)?;
        let shard = self.select_shard(document_id);

        let mut shard_data = self.index_shards[shard].lock().unwrap();
        shard_data.insert(document_id.to_string(), encrypted);

        Ok(format!("Indexed document {} in shard {}", document_id, shard))
    }

    pub fn search(
        &self,
        api_key: &str,
        source_ip: &str,
        query: &str,
    ) -> Result<Vec<String>, String> {
        let client_id = self.compute_client_identity(api_key, source_ip);
        self.check_rate_limit(&client_id)?;

        let mut results = Vec::new();
        for shard in &self.index_shards {
            let data = shard.lock().unwrap();
            for (doc_id, _) in data.iter() {
                if doc_id.contains(query) {
                    results.push(doc_id.clone());
                }
            }
        }
        Ok(results)
    }

    pub fn batch_index(
        &self,
        api_key: &str,
        source_ip: &str,
        documents: Vec<(&str, &[u8])>,
    ) -> Result<Vec<String>, String> {
        let client_id = self.compute_client_identity(api_key, source_ip);
        let doc_count = documents.len() as u32;
        self.check_rate_limit_n(&client_id, doc_count)?;

        let mut results = Vec::new();
        for (doc_id, content) in documents {
            let encrypted = self.encrypt_document(content, doc_id)?;
            let shard = self.select_shard(doc_id);
            let mut shard_data = self.index_shards[shard].lock().unwrap();
            shard_data.insert(doc_id.to_string(), encrypted);
            results.push(format!("Indexed {}", doc_id));
        }
        Ok(results)
    }

    pub fn bulk_search(
        &self,
        api_key: &str,
        source_ip: &str,
        queries: Vec<&str>,
    ) -> Result<HashMap<String, Vec<String>>, String> {
        let client_id = self.compute_client_identity(api_key, source_ip);
        let query_count = queries.len() as u32;
        self.check_rate_limit_n(&client_id, query_count)?;

        let mut all_results = HashMap::new();
        for query in queries {
            let mut results = Vec::new();
            for shard in &self.index_shards {
                let data = shard.lock().unwrap();
                for (doc_id, _) in data.iter() {
                    if doc_id.contains(query) {
                        results.push(doc_id.clone());
                    }
                }
            }
            all_results.insert(query.to_string(), results);
        }
        Ok(all_results)
    }
}
